import {
  booleanAttribute,
  Component,
  EventEmitter,
  Input,
  Output,
  SimpleChanges,
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { TranslateModule } from '@ngx-translate/core';
import { MatCheckboxChange, MatCheckboxModule } from '@angular/material/checkbox';
import { AvatarComponent } from '../../../../../shared/components/avatar/avatar.component';
import { FormsModule } from '@angular/forms';
import { myTeamUsers } from '../../../../../marking/interfaces/teamshare.interface';
import { CommonService } from '../../../../../shared/services/common/common.service';
import { FactService } from '../../../../../shared/services/fact/fact.service';

@Component({
  selector: 'nav-share-permission',
  standalone: true,
  imports: [CommonModule, TranslateModule, MatCheckboxModule, AvatarComponent, FormsModule],
  templateUrl: './nav-share-permission.component.html',
  styleUrl: './nav-share-permission.component.scss',
})
export class NavSharePermissionComponent {
  constructor(
    private common: CommonService,
    private factService: FactService
  ) { }

  @Input() userList: myTeamUsers[];
  @Input() nUserid: string;
  @Input() nCaseid: string;
  @Input() nFactid: string;
  @Input() showBar: boolean = false;
  @Input({ transform: booleanAttribute }) isView: boolean = false;
  checkall: boolean = false;
  Editall: boolean = false;
  Shareall: boolean = false;
  Commentall: boolean = false;
  @Input() creator: string;
  @Input() isDocLink: boolean = false;

  isNoSelectedUser: boolean = false;

  @Output() onEvent = new EventEmitter<any>();
  ngOnChanges(changes: SimpleChanges) {
    if (changes['userList']) {
      this.handleSelectedUserPermissions()
      this.syncHeaderFromRows();
    }
  }

  ngOnInit() {
    this.handleSelectedUserPermissions()
    this.syncHeaderFromRows();
    if (this.userList?.length) {
      this.checkall = this.userList
        .filter((user) => user.nUserid != this.nUserid)
        .every((user) => user.isSelected);
    }
  }

  checkC(ev: MatCheckboxChange, x: myTeamUsers) {
    const selectedUser = this.userList.find(user => user.nUserid === x.nUserid);

    if (selectedUser && ev.checked) {
      // Set default permissions when user is selected
      selectedUser.bCanEdit = true;
      selectedUser.bCanCopy = true;
      selectedUser.bCanReshare = true;
      selectedUser.bCanComment = true;
    } else if (selectedUser && !ev.checked) {
      // Clear permissions when user is deselected
      selectedUser.bCanEdit = false;
      selectedUser.bCanCopy = false;
      selectedUser.bCanReshare = false;
      selectedUser.bCanComment = false;
    }

    this.checkall = this.userList
      .filter((user) => user.nUserid != this.nUserid)
      .every((user) => user.isSelected);
    this.syncHeaderFromRows();
    this.onEvent.emit({ type: 'SELECT-ALL', data: null });
  }

  selectAllUsers(e) {
    if (e.checked) {
      this.userList.forEach((user) => {
        user.isSelected = true;
        user.bCanEdit = true;
        user.bCanCopy = true;
        user.bCanReshare = true;
        user.bCanComment = true;
      });
    } else {
      this.userList.forEach((user) => {
        user.isSelected = false;
        user.bCanEdit = false;
        user.bCanCopy = false;
        user.bCanReshare = false;
        user.bCanComment = false;
      });
    }

    if (e.checked) {
      this.Editall = this.Shareall = this.Commentall = true;
    } else {
      this.Editall = this.Shareall = this.Commentall = false;
    }

    this.onEvent.emit({ type: 'SELECT-ALL', data: null });
  }

  toggleSelectAll(ev: boolean) {
    this.userList.forEach((u) => {
      u.isSelected = ev;
      if (ev) {
        // Set default permissions when selecting
        u.bCanEdit = true;
        u.bCanCopy = true;
        u.bCanReshare = true;
        u.bCanComment = true;
      } else {
        // Clear permissions when deselecting
        u.bCanEdit = false;
        u.bCanCopy = false;
        u.bCanReshare = false;
        u.bCanComment = false;
      }
    });
    this.checkall = ev;
    if (this.checkall) {
      this.Editall = this.Shareall = this.Commentall = true;
    } else {
      this.Editall = this.Shareall = this.Commentall = false;
    }
    this.onEvent.emit({ type: 'SELECT-ALL', data: null });
  }

  toggleEditAll(ev: boolean) {
    this.userList.forEach((u) => {
      if (u.isSelected) {
        u.bCanEdit = ev;
      }
    });
  }

  toggleShareAll(ev: boolean) {
    this.userList.forEach((u) => {
      if (u.isSelected) {
        u.bCanReshare = ev;
      }
    });
  }

  toggleCommentAll(ev: boolean) {
    this.userList.forEach((u) => {
      if (u.isSelected) {
        u.bCanComment = ev;
      }
    });
  }

  // async savePermissions() {
  //   console.log('Saving permissions for:', this.nFactid);
  //   const selectedUsers = this.userList
  //     .filter(
  //       (u) => u.isSelected || u.bCanEdit || u.bCanReshare || u.bCanComment
  //     )
  //     .map((u) => ({
  //       nUserid: u.nUserid,
  //       canEdit: u.bCanEdit,
  //       canReshare: u.bCanReshare,
  //       canComment: u.bCanComment,
  //     }));

  //   console.log('Selected users for permission update:', selectedUsers);

  //   if (selectedUsers.length > 0) {
  //     await this.factService.updatePermissions(this.nFactid, selectedUsers);
  //     console.log('Permissions saved:', selectedUsers);
  //   }
  // }


  handleSelectedUserPermissions() {
    this.isNoSelectedUser = false;
    if (!this.isView) return

    this.isNoSelectedUser = this.userList.filter(x => ((x.nUserid != this.nUserid) && ((x.isSelected && this.isView) || !this.isView))).length == 0;
    // this.userList.filter(x => !((x.nUserid != this.nUserid) && ((x.isSelected && this.isView) || !this.isView))).length == 0;

  }


  syncHeaderFromRows(): void {

    const sel = (this.userList ?? []).filter(u => u.isSelected);
    if (sel.length === 0) {
      this.Editall = this.Shareall = this.Commentall = false;
      return;
    }
    this.Editall = sel.every(u => !!u.bCanEdit);
    this.Shareall = sel.every(u => !!u.bCanReshare);
    this.Commentall = sel.every(u => !!u.bCanComment);
  }

  getselectedcount() {
    return this.userList.filter(x => ((x.nUserid != this.nUserid) && (x.isSelected))).length;
  }

}
